import sys
from math import factorial

n = int(sys.stdin.read().split()[0])
mod = 10**9 + 7

def count(rem):
    if len(rem) <= 1:
        return 1
    first = rem[0]
    rest = rem[1:]
    total = count(rest)
    for i in range(len(rest)):
        total += count(rest[:i] + rest[i + 1:])
    return total

if n <= 11:
    print(count(list(range(n))) % mod)
elif n <= 2500:
    total = 0
    for k in range(n // 2 + 1):
        total += factorial(n) // (factorial(k) * 2 ** k * factorial(n - 2 * k))
    print(total % mod)
else:
    f = [1, 1]
    for i in range(2, n + 1):
        f.append((f[i - 1] + (i - 1) * f[i - 2]) % mod)
    print(f[n])

